# ============================================================
#  wolfXsms Phone Simulator
#  Run inside wolfXsms folder: .\setup-phone.ps1
# ============================================================

Write-Host ""
Write-Host "  Installing phone simulator..." -ForegroundColor Yellow
Write-Host ""

$bytes = [System.Convert]::FromBase64String("")
[System.IO.File]::WriteAllBytes("$PSScriptRoot\src\pages\Simulator.tsx", $bytes)
Write-Host "  [OK] Simulator.tsx" -ForegroundColor Green

Write-Host ""
Write-Host "  Phone simulator installed!" -ForegroundColor Cyan
Write-Host "  Features:" -ForegroundColor White
Write-Host "    - Home screen with clock widget + app icons"
Write-Host "    - Messages app with notification badge"
Write-Host "    - Thread view grouped by sender"
Write-Host "    - Dialer with full keypad"
Write-Host "    - Analog + digital clock (live, Nairobi time)"
Write-Host ""
Write-Host "  Run: npm run dev" -ForegroundColor Yellow
Write-Host ""